// ------------------------------------------------------------------------------- textures
const texCache = new Map();
function patternTexture(p, base) {
  const key = JSON.stringify(p) + base;
  if (texCache.has(key)) return texCache.get(key);
  const cv = document.createElement('canvas'); cv.width = 512; cv.height = 256;
  const c = cv.getContext('2d');
  c.fillStyle = base; c.fillRect(0, 0, 512, 256);
  const n = Math.max(1, Math.min(48, p.count || 8));
  if (p.type === 'stripes') {
    c.fillStyle = p.color || '#000';
    for (let i = 0; i < n; i++) {
      c.beginPath();
      const x0 = i * 512 / n;
      for (let y = 0; y <= 256; y += 8) c.lineTo(x0 + 6 * Math.sin(y * 0.09 + i) + 512 / n * 0.42 * Math.sin(Math.PI * y / 256), y);
      for (let y = 256; y >= 0; y -= 8) c.lineTo(x0 + 6 * Math.sin(y * 0.07 + i), y);
      c.fill();
    }
  } else if (p.type === 'segments') {
    const cols = p.colors && p.colors.length ? p.colors : [base, '#ffffff'];
    const m = Math.max(cols.length, 2);
    for (let i = 0; i < m; i++) { c.fillStyle = cols[i % cols.length]; c.fillRect(i * 512 / m, 0, 512 / m + 1, 256); }
  } else if (p.type === 'bands') {
    c.fillStyle = p.color || '#fff';
    for (let i = 0; i < n; i++) c.fillRect(0, 256 * (0.25 + 0.45 * i / n), 512, 256 * 0.12);
  } else if (p.type === 'spots') {
    c.fillStyle = p.color || '#000';
    for (let i = 0; i < n * 4; i++) { c.beginPath(); c.arc(Math.random() * 512, Math.random() * 256, 6 + Math.random() * 10, 0, 7); c.fill(); }
  } else if (p.type === 'screen') {
    const g = c.createLinearGradient(0, 0, 512, 256); g.addColorStop(0, '#2547c9'); g.addColorStop(1, '#8a2be2');
    c.fillStyle = g; c.fillRect(0, 0, 512, 256);
    c.fillStyle = 'rgba(255,255,255,0.9)'; c.font = 'bold 54px sans-serif'; c.textAlign = 'center';
    c.save(); c.translate(256, 128); c.rotate(Math.PI / 2); c.fillText('1%', 0, 18); c.restore();
  } else if (p.type === 'card') {
    c.fillStyle = '#fbfbf7'; c.fillRect(0, 0, 512, 256);
    c.fillStyle = '#c8102e'; c.font = 'bold 120px serif'; c.textAlign = 'center'; c.fillText('♥', 256, 170);
  } else if (p.type === 'pizza') {
    c.fillStyle = '#c63a1d'; c.fillRect(0, 0, 512, 256);
    c.fillStyle = '#f6d36b';
    for (let i = 0; i < 70; i++) { c.beginPath(); c.arc(Math.random() * 512, Math.random() * 256, 10 + Math.random() * 18, 0, 7); c.fill(); }
    c.fillStyle = '#9e1b16';
    for (let i = 0; i < 14; i++) { c.beginPath(); c.arc(Math.random() * 512, Math.random() * 256, 14, 0, 7); c.fill(); }
  }
  const t = new THREE.CanvasTexture(cv);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = THREE.RepeatWrapping;
  texCache.set(key, t);
  return t;
}

// ------------------------------------------------------------------------------- geometry
const num = (v, d, lo, hi) => { v = +v; if (!isFinite(v)) v = d; return Math.max(lo, Math.min(hi, v)); };

function geometryFor(p) {
  const s = Array.isArray(p.size) ? p.size : [];
  const L = (i, d) => num(s[i], d, 0.0005, 4);
  switch (p.shape) {
    case 'sphere': { const g = new THREE.SphereGeometry(1, 32, 20); g.scale(L(0, 0.1), L(1, s[0] ?? 0.1), L(2, s[0] ?? 0.1)); return g; }
    case 'box': return new THREE.BoxGeometry(L(0, 0.1), L(1, 0.1), L(2, 0.1));
    case 'plate': return new THREE.BoxGeometry(L(0, 0.1), L(1, 0.002), L(2, 0.1));
    case 'roundbox': { const r = num(p.radius, 0.01, 0.0005, Math.min(L(0, .1), L(1, .1), L(2, .1)) / 2.01); return new RoundedBoxGeometry(L(0, 0.1), L(1, 0.1), L(2, 0.1), 3, r); }
    case 'cylinder': {
      const th = p.theta ? [num(p.theta[0], 0, -720, 720) * d2r, num(p.theta[1], 360, 1, 360) * d2r] : [0, Math.PI * 2];
      return new THREE.CylinderGeometry(L(0, 0.05), L(1, s[0] ?? 0.05), L(2, 0.1), 32, 1, false, th[0], th[1]);
    }
    case 'cone': return new THREE.ConeGeometry(L(0, 0.05), L(1, 0.1), 32);
    case 'capsule': return new THREE.CapsuleGeometry(L(0, 0.03), L(1, 0.1), 6, 16);
    case 'torus': return new THREE.TorusGeometry(L(0, 0.1), L(1, 0.02), 12, 32, num(s[2], 360, 10, 360) * d2r);
    case 'dome': { // umbrella-like shell: radius, height
      const R = L(0, 0.4), h = L(1, 0.2), pts = [];
      for (let i = 0; i <= 12; i++) { const a = i / 12; pts.push(new THREE.Vector2(R * Math.sin(a * Math.PI / 2) + 1e-4, h * Math.cos(a * Math.PI / 2) - h)); }
      for (let i = 12; i >= 0; i--) { const a = i / 12; pts.push(new THREE.Vector2(R * Math.sin(a * Math.PI / 2) * 0.985 + 1e-4, h * Math.cos(a * Math.PI / 2) - h - 0.006)); }
      const g = new THREE.LatheGeometry(pts, 32); g.translate(0, h, 0); return g;
    }
    case 'lathe': {
      const pts = (p.points || [[0, 0], [0.05, 0], [0.05, 0.1], [0, 0.1]]).slice(0, 64).map(([r, y]) => new THREE.Vector2(num(r, 0, 0, 4), num(y, 0, -4, 4)));
      return new THREE.LatheGeometry(pts, 32);
    }
    case 'tube': {
      const pts = (p.points || [[-0.1, 0, 0], [0.1, 0, 0]]).slice(0, 32).map(q => new THREE.Vector3(num(q[0], 0, -4, 4), num(q[1], 0, -4, 4), num(q[2], 0, -4, 4)));
      if (pts.length < 2) pts.push(pts[0].clone().add(new THREE.Vector3(0.1, 0, 0)));
      return new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 32, num(p.radius, 0.02, 0.001, 1), 12, false);
    }
    case 'teapot': { const g = new TeapotGeometry(num(s[0], 0.1, 0.01, 2), 6); return g; }
    default: return new THREE.SphereGeometry(L(0, 0.1), 16, 12);
  }
}

const matCache = new Map();
export function makeMaterial(color, kind, pattern) {
  const m = MATERIALS[kind] || MATERIALS.plastic;
  const key = color + kind + JSON.stringify(pattern || null);
  if (matCache.has(key)) return matCache.get(key);
  const opts = { color: new THREE.Color(color), roughness: m.rough, metalness: m.metal };
  let mat;
  if (m.glass) mat = new THREE.MeshPhysicalMaterial({ ...opts, transparent: true, opacity: 0.38, roughness: 0.02, clearcoat: 1, side: THREE.DoubleSide, depthWrite: false });
  else if (m.clear) mat = new THREE.MeshPhysicalMaterial({ ...opts, clearcoat: 0.8, clearcoatRoughness: 0.1 });
  else mat = new THREE.MeshStandardMaterial(opts);
  if (pattern) { mat.map = patternTexture(pattern, color); mat.color.set('#ffffff'); }
  if (m.emissive) { mat.emissive = new THREE.Color(color); mat.emissiveIntensity = 0.7; if (mat.map) mat.emissiveMap = mat.map; }
  if (kind === 'fabric' || kind === 'paper' || p_isThin(pattern)) mat.side = THREE.DoubleSide;
  matCache.set(key, mat);
  return mat;
}
const p_isThin = () => false;

// ------------------------------------------------------------------------------- build
const v3 = new THREE.Vector3();

function hullOf(points) {
  try {
    const h = new ConvexHull().setFromPoints(points);
    let vol = 0;
    const c = new THREE.Vector3();
    for (const p of points) c.add(p);
    c.divideScalar(points.length);
    const tris = [];
    for (const f of h.faces) {
      let e = f.edge; const a = e.head().point;
      e = e.next;
      do { const b = e.head().point, d = e.next.head().point; tris.push(a, b, d); vol += Math.abs(new THREE.Vector3().subVectors(a, c).dot(new THREE.Vector3().subVectors(b, c).cross(new THREE.Vector3().subVectors(d, c)))) / 6; e = e.next; } while (e.next !== f.edge);
    }
    const cen = new THREE.Vector3();
    // volume-weighted centroid of tetrahedra
    let vw = 0;
    for (let i = 0; i < tris.length; i += 3) {
      const a = tris[i], b = tris[i + 1], d = tris[i + 2];
      const tv = Math.abs(new THREE.Vector3().subVectors(a, c).dot(new THREE.Vector3().subVectors(b, c).cross(new THREE.Vector3().subVectors(d, c)))) / 6;
      cen.addScaledVector(new THREE.Vector3().add(a).add(b).add(d).add(c), tv / 4); vw += tv;
    }
    if (vw > 0) cen.divideScalar(vw); else cen.copy(c);
    return { volume: Math.max(vol, 1e-9), centroid: cen, tris };
  } catch (e) { return null; }
}

function samplePositions(geo, matrix, max = 160) {
  const pos = geo.attributes.position, n = pos.count, out = [];
  const step = Math.max(1, Math.floor(n / max));
  for (let i = 0; i < n; i += step) out.push(new THREE.Vector3().fromBufferAttribute(pos, i).applyMatrix4(matrix));
  return out;
}

// Validate and normalise a recipe (used for Claude-generated ones).
export function sanitizeRecipe(r) {
  const out = {
    id: r.id || ('gen-' + Math.random().toString(36).slice(2, 8)),
    name: String(r.name || 'Mystery object').slice(0, 40),
    icon: typeof r.icon === 'string' ? r.icon.slice(0, 4) : '✨',
    mass: num(r.mass, 1, 0.001, 5000),
    toughness: num(r.toughness, 20, 0.01, 1e6),
    impact: num(r.impact, 0, 0, 1e7),
    unbreakable: !!r.unbreakable, pop: !!r.pop,
    spray: SPRAYS.includes(r.spray) ? r.spray : 'dust',
    sound: SOUNDS.includes(r.sound) ? r.sound : 'crunch',
    inner: /^#[0-9a-f]{6}$/i.test(r.inner) ? r.inner : '#cccccc',
    aero: r.aero === 'plate' ? 'plate' : 'auto',
    count: Math.round(num(r.count, 1, 1, 30)),
    blend: String(r.blend || 'IT BLENDS.').slice(0, 120),
    survive: String(r.survive || 'IT DID NOT BLEND.').slice(0, 120),
    fact: r.fact ? String(r.fact).slice(0, 240) : '',
    parts: [],
  };
  const parts = Array.isArray(r.parts) ? r.parts.slice(0, 40) : [];
  for (const p of parts) {
    if (!p || typeof p !== 'object') continue;
    out.parts.push({
      shape: ['sphere', 'box', 'plate', 'roundbox', 'cylinder', 'cone', 'capsule', 'torus', 'dome', 'lathe', 'tube', 'teapot'].includes(p.shape) ? p.shape : 'box',
      size: Array.isArray(p.size) ? p.size.slice(0, 3) : [0.1, 0.1, 0.1],
      pos: Array.isArray(p.pos) ? p.pos.slice(0, 3).map(v => num(v, 0, -4, 4)) : [0, 0, 0],
      rot: Array.isArray(p.rot) ? p.rot.slice(0, 3).map(v => num(v, 0, -720, 720)) : [0, 0, 0],
      color: /^#[0-9a-f]{6}$/i.test(p.color) ? p.color : '#999999',
      material: MATERIALS[p.material] ? p.material : 'plastic',
      pattern: p.pattern && typeof p.pattern === 'object' ? p.pattern : undefined,
      points: Array.isArray(p.points) ? p.points : undefined,
      radius: p.radius, theta: Array.isArray(p.theta) ? p.theta : undefined, round: !!p.round,
    });
  }
  if (!out.parts.length) out.parts.push({ shape: 'box', size: [0.2, 0.2, 0.2], pos: [0, 0, 0], rot: [0, 0, 0], color: '#888888', material: 'plastic' });
  return out;
}

// Build meshes + physics data for one instance. Returns
// { group, parts:[{mesh, points (body frame, about COM), volume, mass, plate, round, matKind, color, rest}], volume, radius }
export function buildObject(recipe) {
  const group = new THREE.Group();
  const raw = [];
  for (const p of recipe.parts) {
    const geo = geometryFor(p);
    const mat = makeMaterial(p.color, p.material, p.pattern);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true; mesh.receiveShadow = true;
    const pos = p.pos || [0, 0, 0], rot = p.rot || [0, 0, 0];
    mesh.position.set(pos[0] || 0, pos[1] || 0, pos[2] || 0);
    mesh.rotation.set((rot[0] || 0) * d2r, (rot[1] || 0) * d2r, (rot[2] || 0) * d2r);
    mesh.updateMatrix();
    const pts = samplePositions(geo, mesh.matrix);
    const hull = hullOf(pts);
    if (!hull) { geo.dispose(); continue; }
    let plate = null;
    const thinPlate = p.shape === 'plate' || (p.shape === 'cylinder' && recipe.aero === 'plate');
    if (thinPlate) {
      geo.computeBoundingBox();
      const bb = geo.boundingBox, sz = new THREE.Vector3().subVectors(bb.max, bb.min);
      // thinnest axis is the plate normal
      const ax = sz.x < sz.y && sz.x < sz.z ? 0 : sz.y < sz.z ? 1 : 2;
      const n = new THREE.Vector3(ax === 0 ? 1 : 0, ax === 1 ? 1 : 0, ax === 2 ? 1 : 0).applyEuler(mesh.rotation);
      const dims = [sz.x, sz.y, sz.z].filter((_, i) => i !== ax);
      let A = dims[0] * dims[1];
      if (p.shape === 'cylinder' && p.theta) A = Math.PI * (num(p.size[0], .1, 0, 4) ** 2) * num(p.theta[1], 360, 1, 360) / 360;
      plate = { c: hull.centroid.clone(), n, A, chord: Math.sqrt(A) };
    }
    raw.push({ mesh, geo, pts, hull, plate, round: p.round ? num(p.size?.[0], 0.1, 0.001, 4) : 0, matKind: p.material, color: p.color, rest: (MATERIALS[p.material] || MATERIALS.plastic).rest, shape: p.shape });
  }
  const totalVol = raw.reduce((s, r) => s + r.hull.volume, 0) || 1e-6;
  // centre of mass (parts get mass ∝ hull volume)
  const com = new THREE.Vector3();
  for (const r of raw) com.addScaledVector(r.hull.centroid, r.hull.volume / totalVol);
  let radius = 0;
  const parts = raw.map(r => {
    r.mesh.position.sub(com); r.mesh.updateMatrix();
    for (const p of r.pts) p.sub(com);
    for (const p of r.pts) radius = Math.max(radius, p.length());
    if (r.plate) r.plate.c.sub(com);
    group.add(r.mesh);
    return { mesh: r.mesh, points: r.pts, volume: r.hull.volume, mass: recipe.mass * r.hull.volume / totalVol, plate: r.plate,
      round: r.round, matKind: r.matKind, color: r.color, rest: r.rest, center: r.hull.centroid.clone().sub(com), shape: r.shape };
  });
  return { group, parts, volume: totalVol, radius: Math.max(radius, 0.01) };
}

